/** WS-USER-FEC PIC 9(13) RECEIVED BY CONTENT, interpretado con WS-PARAM-USERFEC y WS-PARAM-CUF. */
public record ParametroMonitoreo(TipoReporte tipo,   // WS-PARAM-DECI  9(01)
                                 int user,           // WS-PARAM-USER  9(04)
                                 int sistema,        // WS-PARAM-U     9(03): últimos 3 dígitos del USER
                                 LocalDate fecha) {  // WS-PARAM-FEC   9(08) AAAAMMDD

    public enum TipoReporte { MONITOREO, MONIBATCH }

    public static ParametroMonitoreo parse(String p13) {
        if (p13 == null || !p13.matches("\\d{13}")) {
            throw new IllegalArgumentException("Parámetro de 13 dígitos inválido: " + p13);
        }
        TipoReporte tipo = p13.charAt(0) == '1' ? TipoReporte.MONITOREO : TipoReporte.MONIBATCH;
        int user = Integer.parseInt(p13.substring(1, 5));
        int sistema = Integer.parseInt(p13.substring(2, 5));    // vista CUF: D(1) C(1) U(3) F(8)
        LocalDate fecha = LocalDate.parse(p13.substring(5), DateTimeFormatter.BASIC_ISO_DATE);
        return new ParametroMonitoreo(tipo, user, sistema, fecha);
    }
}

/** REG-PROGRAMA: datos de un programa y, si existe, de una de sus actividades. */
public record TareaMonitoreada(
        int numAgrupador, String nomAgrupador,        // MON-NUM-AGRUP 9(02) / X(40)
        int tipoProg, int numProg, int numCopia,      // 1 = proceso, 2 = librería
        String nomPrograma,
        LocalDate fecIni, LocalTime hraIni,           // 9(08) AAAAMMDD / HHMMSSCC
        LocalDate fecFin, LocalTime hraFin,
        Duration etAnterior, Duration etActual,       // 9(10) HHHHMMSSCC
        int avancePct, Duration tiempoEsperado, int tipoDespliegue,
        Actividad actividad) {                         // null cuando el programa no tiene actividades

    public record Actividad(int num, int tipo, String nombre, int avancePct,
                            Duration etAnterior, Duration etActual, Duration tiempoEsperado,
                            String textoAdicional, long transacciones,
                            BigDecimal tranXSeg,           // 9(08)V99    -> escala 2
                            BigDecimal tiempoPromResp,     // 9(06)V9(06) -> escala 6
                            String seEncuentraEn, Estado estado) {}

    public enum Estado { EN_PROCESO, TERMINADA, NO_INICIADA, SIN_ESTADO }
}

