/** 50031000-LEO-ARCH: Classifier que decide qué filas entran al listado. */
@Component
@RequiredArgsConstructor
public class FiltroAgrupador implements ItemProcessor<TareaMonitoreada, TareaMonitoreada> {

    private final ParametroMonitoreo parametro;
    private final MonitoreoProperties props;            // p140.umbral-agrupador-batch: 6

    @Override
    public TareaMonitoreada process(TareaMonitoreada t) {
        boolean esBatch = t.numAgrupador() >= props.umbralAgrupadorBatch();
        return switch (parametro.tipo()) {
            case MONITOREO -> esBatch ? null : t;       // IF MON-NUM-AGRUP < 6
            case MONIBATCH -> esBatch ? t : null;       // IF MON-NUM-AGRUP > 5
        };
    }
}
